12	)
13	
14	// DispatchMemoCreatedWebhook dispatches a webhook when a memo is created.
15	func (s *APIV1Service) DispatchMemoCreatedWebhook(ctx context.Context, memo *v1pb.Memo) error {
16		return s.dispatchMemoRelatedWebhook(ctx, memo, "memos.memo.created")
17	}
18	
19	// DispatchMemoUpdatedWebhook dispatches webhook when memo is updated.
20	func (s *APIV1Service) DispatchMemoUpdatedWebhook(ctx context.Context, memo *v1pb.Memo) error {
21		return s.dispatchMemoRelatedWebhook(ctx, memo, "memos.memo.updated")
22	}
23	
24	// DispatchMemoDeletedWebhook dispatches webhook when memo is deleted.
25	func (s *APIV1Service) DispatchMemoDeletedWebhook(ctx context.Context, memo *v1pb.Memo) error {
26		return s.dispatchMemoRelatedWebhook(ctx, memo, "memos.memo.deleted")
27	}
28	
29	// DispatchMemoCommentCreatedWebhook dispatches webhook to the related memo owner when a comment is created.
30	func (s *APIV1Service) DispatchMemoCommentCreatedWebhook(ctx context.Context, commentMemo *v1pb.Memo, relatedMemoCreatorID int32) error {
31		webhooks, err := s.Store.GetUserWebhooks(ctx, relatedMemoCreatorID)
32		if err != nil {
33			return err
34		}
35		for _, hook := range webhooks {
36			payload, err := convertMemoToWebhookPayload(commentMemo)
37			if err != nil {
38				return errors.Wrap(err, "failed to convert memo to webhook payload")
39			}
40			payload.ActivityType = "memos.memo.comment.created"
41			payload.URL = hook.Url
42			payload.SigningSecret = hook.SigningSecret
43			webhook.PostAsync(payload)
44		}
45		return nil
46	}
47	
48	func (s *APIV1Service) dispatchMemoRelatedWebhook(ctx context.Context, memo *v1pb.Memo, activityType string) error {
49		creator, err := ResolveUserByName(ctx, s.Store, memo.Creator)
50		if err != nil {
51			return status.Errorf(codes.InvalidArgument, "invalid memo creator")
52		}
53		if creator == nil {
54			return status.Errorf(codes.NotFound, "memo creator not found")
55		}
56		creatorID := creator.ID
